package com.tarapickle.identity.domain.repository; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import org.springframework.stereotype.Repository; import java.util.*;
@Repository public interface UserRoleRepository extends org.springframework.data.repository.Repository<com.tarapickle.identity.domain.model.Role,UUID>{ @Modifying @Query(value="insert into user_roles(user_id,role_id) values (:uid,:rid)",nativeQuery=true) void assign(@Param("uid") UUID uid,@Param("rid") UUID rid); @Query(value="select r.code from roles r join user_roles ur on ur.role_id=r.id where ur.user_id=:uid",nativeQuery=true) Set<String> roles(@Param("uid") UUID uid); }
